guS(){return"\uba3c\uc800 \ub85c\uceec OCR \uc11c\ubc84 URL\uc744 \uc785\ub825\ud558\uc138\uc694."},
guT(){return"\ub85c\uceec OCR \uc11c\ubc84\uac00 \uc2e4\ud589 \uc911\uc774\uba70 \uc900\ube44\ub418\uc5c8\uc2b5\ub2c8\ub2e4."},
guR(){return"\ub85c\uceec OCR \uc11c\ubc84\uc5d0 \uc5f0\uacb0\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \uc548\ub0b4, \ubc29\ud654\ubcbd, URL\uc744 \ud655\uc778\ud558\uc138\uc694."},
