nS(a,b){return"\u041e\u0431\u0449\u0430\u044f \u0432\u0435\u0440\u043e\u044f\u0442\u043d\u043e\u0441\u0442\u044c \u0418\u0418 \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 "+a+"%, \u0447\u0442\u043e \u0434\u043e\u0441\u0442\u0438\u0433\u0430\u0435\u0442 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u0432\u0430\u043c\u0438 \u043f\u043e\u0440\u043e\u0433\u0430 \u043c\u0430\u0440\u043a\u0438\u0440\u043e\u0432\u043a\u0438 \u0418\u0418 "+b+"%, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043e\u0442\u0447\u0451\u0442 \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442 \u044d\u0442\u043e\u0442 \u0442\u0435\u043a\u0441\u0442 \u043a\u0430\u043a \u0418\u0418. \u041f\u0435\u0440\u0435\u0434 \u043f\u0440\u0438\u043d\u044f\u0442\u0438\u0435\u043c \u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043e\u0437\u043d\u0430\u043a\u043e\u043c\u044c\u0442\u0435\u0441\u044c \u0441 \u0434\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430\u043c\u0438 \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0439 \u0438 \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u044f\u043c\u0438 \u0434\u0432\u0438\u0436\u043a\u043e\u0432."},
